// Simulation of nested asynchronous callback hell
function getUser(userId, callback) {
  setTimeout(() => {
    console.log("1. Fetched user profile");
    callback(null, { id: userId, username: "alex" });
  }, 500);
}

function getOrders(username, callback) {
  setTimeout(() => {
    console.log("2. Fetched user orders");
    callback(null, ["Order-101", "Order-102"]);
  }, 500);
}

// Deep nesting / pyramid of doom makes error handling fragile
getUser(42, (err, user) => {
  if (err) return console.error(err);

  getOrders(user.username, (err, orders) => {
    if (err) return console.error(err);
    console.log(`User ${user.username} has orders:`, orders);
  });
});

function fetchUserData(userId) {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      if (userId > 0) {
        // Transition from 'pending' to 'fulfilled'
        resolve({ id: userId, name: "Diana", plan: "Pro" });
      } else {
        // Transition from 'pending' to 'rejected'
        reject(new Error("Invalid User ID: ID must be positive"));
      }
    }, 600);
  });
}

// Consuming promise using .then(), .catch(), and .finally()
fetchUserData(105)
  .then((data) => {
    console.log("User data retrieved:", data);
    return data.plan;
  })
  .then((plan) => console.log("Current plan:", plan))
  .catch((error) => console.error("Encountered error:", error.message))
  .finally(() => console.log("Operation completed."));

const delay = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

async function performOrderCheckout(cartId) {
  try {
    console.log("Initiating checkout for cart:", cartId);

    // 'await' pauses function execution until promise resolves
    await delay(400);
    const inventoryAvailable = true;

    if (!inventoryAvailable) {
      throw new Error("Items are currently out of stock");
    }

    await delay(300);
    const paymentConfirmation = { confirmationCode: "CONF-8823", status: "Paid" };

    return paymentConfirmation;
  } catch (error) {
    console.error("Checkout failed:", error.message);
    throw error; // Re-throw or handle gracefully
  } finally {
    console.log("Checkout cleanup finished.");
  }
}

// Calling async function
performOrderCheckout("cart_991").then(res => console.log("Result:", res));
